EXTRA_RULES = r"""
материал и исполнение|материалы конструкции^Материал нового кузова выбирают в составе технического решения. Название распространённой марки стали или увеличение толщины само по себе не доказывает пригодности всей конструкции. Имеют значение назначение деталей, свойства груза, технология изготовления и сопряжение с базовым вагоном.^Запросите согласованную документацию на конструкцию и подтверждения материалов поставки. Если предлагается замена материала, её оформляют как изменение решения с проверкой последствий, а не как незаметную коммерческую замену.^Что предусмотрено проектом;Как подтверждается материал;Как согласуются изменения^Более тяжёлая конструкция не всегда является улучшением: изменение массы и сопряжений требует технической оценки.^Документированное исполнение конструкции и подтверждение использованных материалов.
\Aгеометрия кузова|деформации сопряжений^Состояние геометрии нужно отделять от локальных повреждений поверхности. Внешне восстановленная обшивка может не показывать положение несущих элементов. Для нового кузова важны размеры сопряжений, для существующего — фактические отклонения и основания их технической оценки.^Получите ведомость измерений и указание участков проверки. Решение о восстановлении или смене элемента принимает специалист по согласованной документации. До измерений выводы по фотографиям остаются предварительными.^Что измерено фактически;Какие участки влияют на монтаж;Каким решением подтверждается восстановление^Изготовление сопряжённой детали по номинальным размерам может не учитывать деформацию существующего вагона.^Проверенная геометрия и технически обоснованные условия дальнейшего монтажа.
необходимость нового исполнения^Изменение назначения или режима работы отличается от восстановления прежней конструкции. Новый кузов может потребоваться не только из-за износа, но и из-за новой технологической задачи. В таком случае важно описать желаемое изменение и проверить его совместимость с сохраняемыми элементами.^Сравните исходное и требуемое исполнение в техническом задании. Отдельно укажите свойства груза, работу терминалов и ограничения базового вагона. Решение должно описывать именно согласованный вариант изменения.^Что меняется в рабочем процессе;Какие узлы затрагиваются;Что должно остаться прежним^Смета обычного ремонта может не включать проектные работы и детали для изменённого назначения.^Техническое задание с описанием различий исходного и нового исполнения.
сопоставимость вариантов^Ремонт, модернизацию и покупку сравнивают для одной производственной задачи и общего горизонта. Один вариант может восстанавливать часть функций, другой давать готовый новый объект. Без одинаковых границ результата начальная цена не объясняет экономику выбора.^В таблице укажите состав, срок, расходы на ввод и требования к инфраструктуре. Отметьте допущения о сохраняемых узлах и будущих работах. Расчёт простоя берут из данных самого предприятия.^Какой результат одинаков у вариантов;Что различается;На чём основаны будущие расходы^Можно выбрать меньшую начальную сумму, которая не включает необходимые последующие операции.^Сравнительная таблица с одинаковыми границами и явными допущениями.
восстановительные операции^Восстановление должно иметь определённый объект и техническое основание. Название ремонта не описывает, какие поверхности, детали и соединения будут затронуты. Для составления сметы важны фактические дефекты и выбранный ремонтный маршрут, а не одинаковый набор операций для всей партии.^Попросите построчную связь дефекта, решения и операции. Уточните, что определяется после разборки и какой порядок согласования предусмотрен. Не задавайте технологию восстановления без заключения ответственного специалиста.^Какой дефект устраняется;Каким решением определены операции;Как подтверждается результат^Универсальная строка в смете может скрывать разные объёмы работ и затруднить приёмку.^Ведомость восстановительных операций, связанных с конкретными результатами обследования.
замена комплектующих|покупка новых деталей^Новые детали в ремонте нужно учитывать по обозначению, количеству и комплектности. Не всякая замена улучшает проект: требуется совместимость с сохраняемыми элементами. Для сравнения цены важно понять, кто закупает компоненты и кто отвечает за их проверку и установку.^Составьте спецификацию с подтверждёнными исполнениями. Отдельно обозначьте детали заказчика, поставку исполнителя и согласование возможного аналога. Приёмка документов на комплектующие входит в общий порядок передачи.^Какие детали действительно нужны;Кто обеспечивает поставку;Как согласуются аналоги^Отдельно дешёвая деталь может потребовать непредусмотренной адаптации или оказаться неприменимой к сборке.^Согласованная спецификация заменяемых элементов и распределение ответственности.
\Aмонтаж\Z|монтаж и регулировка|монтаж и проверка^Монтаж является отдельной границей между изготовлением элемента и получением готового результата. Для него нужны подготовленный базовый объект, подтверждённые сопряжения и необходимые ресурсы площадки. Деталь, отгруженная изготовителем, ещё не равна принятому узлу или вагону после установки.^Определите место, исполнителя и состав монтажных операций. Подготовку и восстановление сопряжений перечислите отдельно. Проверку результата выполняют по согласованной документации и программе профильных специалистов.^Где выполняется монтаж;Кто готовит основание;Что проверяется после установки^Цена изготовления без монтажных работ может не учитывать существенную часть бюджета и времени.^Готовый установленный элемент с предусмотренными подтверждениями результата.
защита поверхности^Покрытие и подготовка поверхности выбираются под изделие и условия работы. Внешний цвет не подтверждает качество подготовки и долговечность конкретного исполнения. Для кузова, работающего с абразивным грузом, нужно отдельно оценить конструкцию и условия содержания, не приписывая покрытию универсальные свойства.^Согласуйте требования к подготовке, покрытию и контролю по документации проекта. Отдельно укажите, какие поверхности обрабатываются и входят ли эти работы в цену изготовленного или ремонтируемого элемента.^Какие поверхности охвачены;Какое исполнение согласовано;Чем проверяется результат^Можно сравнить цены конструкций с разным объёмом подготовки и получить неодинаковые условия дальнейшего содержания.^Согласованный состав подготовки и защиты поверхности.
\Aобслуживание\Z|ремонтные обязательства|порядок обслуживания^Закупка должна учитывать дальнейшее содержание, доступ к узлам и распределение ремонтных обязанностей. Новый объект не освобождает от предусмотренного обслуживания, а финансирование может определять, кто оплачивает отдельные действия. Для старого парка важен накопленный опыт повторяющихся проблем.^Запросите документацию исполнения и требования к содержанию. План предприятия должен учитывать доступность площадок, комплектующих и необходимых ресурсов. Конкретные интервалы и операции берут из применимой документации.^Кто организует обслуживание;Какие ресурсы необходимы;Как распределены расходы^Низкая цена закупки может сочетаться с неудобным обслуживанием или неучтёнными обязательствами покупателя.^Понятный план содержания и распределение обязанностей участников.
компетенция исполнителя|опыт исполнителя^Для сложного ремонта важно проверить, какие работы исполнитель способен выполнить на конкретной модели и какими ресурсами располагает. Общий опыт с вагонами не подтверждает автоматически возможность любого проекта модернизации. Обсуждение компетенций должно относиться к заявленному объёму.^Запросите технический маршрут, распределение работ и подтверждения компетенций по предусмотренным операциям. Если часть проекта передаётся другому участнику, выясните границы ответственности и порядок контроля.^Кто выполняет ключевые операции;Какие ресурсы доступны;Как контролируются привлечённые участники^Универсальное рекламное описание может скрывать зависимость от неподтверждённой внешней площадки.^Подтверждённая схема исполнения конкретного проекта.
оценка выявленных дефектов^Результат измерения или контроля и решение о дальнейшей судьбе детали — разные стадии. Закупщик получает документы и обеспечивает прослеживаемость, но технический вывод о пригодности делает ответственный специалист. Важно согласовать, какие решения возможны по завершённой программе.^В заключении должны быть понятны объект, выявленные обстоятельства и выбранное действие. Неполный контроль или отсутствующие исходные данные отмечаются как ограничения решения, а не как положительный результат.^Кто принимает решение;Какие данные его обосновывают;Какие ограничения остаются^Протокол без интерпретации может быть ошибочно принят за разрешение сохранить весь узел.^Заключение по обследованному объекту с обоснованным дальнейшим действием.
запирающие элементы^Запирающие элементы согласуют вместе с бортом или люком и сопряжёнными деталями. Важно понимать не только наличие отдельной детали, но и исполнение всего механизма. После ремонта или поставки её проверка относится к готовому узлу по документации, а не к внешнему сходству.^Попросите состав механизма, обозначения и сведения о состоянии сопряжений. Разделите комплект поставки и операции восстановления на вагоне. Неопределённое исполнение лучше уточнить до закупки детали.^Каково исполнение механизма;Что меняется вместе с ним;Как принимается готовый узел^Новый элемент может не устранить проблему, если повреждены другие части запирающего механизма.^Комплект согласованного исполнения и предусмотренный контроль после установки.
комплект уплотнений^Уплотняющие элементы являются частью конкретного исполнения узла. Их закупку связывают с идентификацией цилиндра и установленной причиной неисправности. Доступность комплекта с похожим названием не подтверждает совместимость, а замена уплотнений не доказывает пригодности корпуса и рабочих поверхностей.^В заказе укажите обозначение узла и согласованный состав комплектующих. Исполнитель определяет необходимые операции по результатам диагностики. Готовность после ремонта подтверждают предусмотренной проверкой.^Для какого исполнения комплект;Какие поверхности проверены;Что входит в ремонтную цену^Дешёвый комплект расходных деталей может не решить неисправность другого элемента цилиндра.^Идентифицированный комплект и проверенный результат ремонта узла.
последовательность операций^При неисправности механизма полезно описывать наблюдаемую последовательность: на каком этапе появляется отклонение и при каких условиях оно замечено. Это исходная информация для диагностики, а не инструкция по самостоятельному вмешательству. Причина может находиться в сопряжённом узле.^Передайте описание симптома, доступную документацию и сведения о предыдущих работах. Программу проверки согласует профильный исполнитель. Неизвестные обстоятельства помечают отдельно, чтобы не превращать предположение в установленный факт.^На каком этапе появляется проблема;Что изменялось ранее;Какие данные нужны исполнителю^Заказ конкретной детали по одному симптому может не устранить причину неисправности.^Описание проявлений и согласованный диагностический маршрут.
система управления^Систему управления рассматривают вместе с приводом и механическими узлами. Отказ функции нельзя автоматически приписывать одному цилиндру или борту. Исполнение и проверку системы определяют по документации конкретного вагона, сохраняя связь с остальными элементами механизма.^Запросите идентификацию системы, описание проявления и согласованную программу диагностики. Изменения исполнения рассматривают как техническое решение, а не как неформальную настройку на месте.^Что входит в систему;Что подтверждено диагностикой;Как проверяется совместная работа^Замена механической детали может оставить проблему управления, если её не включили в обследование.^Результат проверки системы в составе согласованного механизма.
условия подачи рабочего ресурса^Условия работы привода проверяют вместе с параметрами объекта и исполнением системы. Наблюдаемое отклонение не всегда означает неисправность самого узла. Подтверждение условий подачи и их соответствия проекту выполняется профильными специалистами по документации.^В заявке укажите известные условия площадки и проявление проблемы. Согласуйте, кто проверяет внешние условия и где проходит граница ответственности между вагоном и объектом.^Какие условия требуются;Что имеется на площадке;Кто подтверждает соответствие^Без разграничения объекта и внешней системы стороны могут по-разному объяснять причину отказа функции.^Документированное соответствие условий площадки выбранному исполнению.
проверка полного цикла^Полный цикл показывает работу сопряжённых элементов после устранения причины неисправности. Принятие отдельной детали не заменяет подтверждение функции механизма в согласованном составе. Критерии проверки устанавливают по проекту и документации, не по общему рекламному описанию.^Укажите программу, ответственных и форму результата. Сохраняемые и новые элементы должны быть отражены в перечне комплекта. Если проверка на площадке заказчика отличается от проверки исполнителя, эту границу фиксируют заранее.^Какая функция подтверждается;Где выполняется проверка;Какие условия необходимы^Работа одного отремонтированного элемента может быть ошибочно принята за готовность всей системы.^Подтверждённый результат согласованной функциональной проверки.
состояние балки^Балку учитывают отдельно от боковых рам, колесных пар и других элементов тележки. При новой поставке важны исполнение и комплектность, при ремонте — фактическое состояние и решение специалиста. Пригодность соседних деталей не подтверждает автоматически возможность сохранить этот элемент.^Попросите идентификацию и результаты предусмотренного контроля. Ведомость тележки должна показывать выбранное действие по балке и связь с готовой сборкой. Возможность восстановления определяется техническим решением.^Как идентифицирована деталь;Что показало обследование;Каково её место в сборке^Общая цена ремонта тележки может скрыть отдельную замену существенного элемента.^Поэлементное решение и комплект документов по принятому исполнению.
группы состояния^Однородное обозначение партии не означает одинаковую трудоёмкость. Перед расчётом полезно разделить объекты по документированному состоянию и уже известным дефектам. Группировка помогает планировать, но не отменяет индивидуального решения, если результаты обследования различаются.^В реестре укажите критерий каждой группы и номера относящихся к ней объектов. Уточняйте состав после диагностики, сохраняя связь первоначальных и окончательных решений. Стоимость должна показывать, что включено для каждой группы.^Почему объекты объединены;Что может изменить группу;Как рассчитывается разница^Единая цена без границ состояния может создать спор о дополнительных работах после приёмки партии исполнителем.^Реестр групп с критериями и порядком уточнения состава.
минимальный рабочий парк^Вывод вагонов на ремонт должен учитывать потребность производства в работающем парке. Согласование общей длительности проекта не показывает, сколько единиц доступно в каждый момент. Поэтому технический график связывают с очередями передачи и фактическим оборотом объекта.^Заказчик определяет рабочий минимум по своим потокам. Исполнитель подтверждает график приёма и возврата. Если возможны задержки комплектующих или уточнение дефектов, предусмотрите порядок согласования изменения очереди.^Сколько единиц должно работать;Когда передаются очереди;Как меняется график^Удобная подрядчику единовременная передача партии может остановить технологический процесс заказчика.^Согласованные ограничения вывода парка и поэтапный график.
резерв графика|сезонная нагрузка^Резерв сроков нужен для конкретных зависимостей, а сезонную потребность рассчитывает предприятие. Не стоит заменять неизвестность произвольной общей надбавкой. Перечислите события, которые могут задержать следующий этап, и действия при их наступлении.^Для графика нужны данные о загрузке производства, получении документов и комплектующих. Согласуйте раннее уведомление и возможную перестановку очереди. Реальные критические даты отмечайте отдельно от желательных.^Какие зависимости критичны;Когда нужно уведомление;Какие очереди можно изменить^План без учёта пикового периода может создать дефицит рабочих единиц в момент максимальной потребности.^График с объяснёнными резервами и порядком изменения очередности.
налоговый режим|налоги и комиссии^Цена с налогами и цена без них не сопоставимы без уточнения условий. В предложении должны быть понятны состав суммы, применимый налоговый режим и дополнительные платежи. Для лизинга финансовые обязательства рассматриваются вместе с графиком и условиями договора.^Попросите письменную расшифровку цены и платежей. Финансовая служба предприятия проверяет влияние условий на свой расчёт. Не переносите рекламную цифру в бюджет, если её налоговая и договорная база не определена.^Как представлена цена;Какие платежи добавляются;Что подтверждено адресным предложением^Разница формата указания суммы может быть ошибочно принята за скидку или экономию.^Расшифрованная цена и перечень предусмотренных платежей.
транспортные расходы^Логистика зависит от предмета поставки, места передачи и принимающей площадки. Перевозка отдельного кузова, узла и готового вагона имеет разные организационные условия. В смете полезно выделить подготовку, отправку и необходимые операции на обоих концах.^Согласуйте адреса, границы транспортной ответственности и состав включённых действий. Для объёмной конструкции отдельно уточните готовность площадки и ресурсов приёмки. Стоимость берут из адресного расчёта.^Где начинается доставка;Какие операции включены;Кто готовит приёмную сторону^Цена изделия с передачей на складе может не отражать полную стоимость его получения на объекте.^Согласованный маршрут передачи и адресный расчёт транспортного блока.
аванс^Аванс оценивают вместе с датой доступности объекта, остальными платежами и условиями возврата или изменения заказа. Он влияет на потребность предприятия в денежных средствах до начала полезной работы. Одна доля первоначального платежа не описывает полную экономику сделки.^Попросите адресный график и связь платежа с предметом поставки. Финансовая служба сопоставляет варианты на одинаковой комплектации и сроке. Порядок изменения проекта должен быть понятен до перечисления суммы.^За какой объект вносится платёж;Когда требуется сумма;Как связаны платёж и готовность^Малый аванс может сочетаться с другими крупными платежами или более поздним получением объекта.^График платежей с понятным первоначальным этапом.
график платежей^Денежные потоки сравнивают по датам и полному составу обязательств. Для закупки и финансирования важно знать, когда перечисляется каждая сумма и когда предприятие получает рабочий объект. Разница между началом платежей и вводом может влиять на выбор варианта.^Получите график по согласованному предмету сделки. Выделите регулярные, разовые и конечные платежи, а также условия пересмотра. Финансовую оценку выполняют с учётом данных предприятия и договорных условий.^Какие даты предусмотрены;Когда объект начинает работать;Какие суммы могут измениться^Сравнение только одного ежемесячного платежа не показывает полного бюджета и сроков движения денег.^Полный адресный график обязательств.
страхование^Страховые условия при финансировании или поставке являются самостоятельной частью бюджета и ответственности. Важно понять, когда начинается покрытие, какой объект описан и кто несёт расходы. Общая запись о страховке не объясняет действия при конкретном событии.^Запросите условия и перечень платежей, если страхование предусмотрено сделкой. Согласуйте границы по перевозке, хранению и эксплуатации с ответственными специалистами. Не считайте неподтверждённое покрытие автоматически действующим.^Какой объект застрахован;Кто оплачивает условия;Как оформляется обращение^Цена финансирования без предусмотренных страховых расходов может не отражать полную стоимость выбранного варианта.^Согласованные страховые обязательства и порядок взаимодействия сторон.
передача и выкуп^Получение вагона и переход прав по итогам финансирования могут относиться к разным стадиям. Для предприятия важно понимать порядок передачи, конечные платежи и условия завершения сделки. Предположение о выкупе не должно заменять конкретные положения договора.^Получите адресное описание этапов и документов. Сопоставьте их с графиком денег и реальными условиями поставки. Решение о финансировании согласуется финансовой и договорной службами предприятия.^Когда передаётся объект;Что требуется для завершения;Какие конечные платежи предусмотрены^Низкие текущие платежи могут сопровождаться дополнительным условием в конце срока.^Согласованный порядок передачи и завершения финансирования.
досрочного завершения^Досрочное завершение финансирования или заказа может иметь отдельные условия, отличающиеся от обычного графика. Возможность предприятия изменить планы лучше обсудить до подписания. Самостоятельно считать остаток как простую сумму будущих платежей без проверки договора не следует.^Попросите порядок расчёта и перечень необходимых согласований. Финансовый специалист оценивает условия на адресном предложении, включая возможные платежи и судьбу объекта. Альтернативы сравнивают на одинаковой исходной задаче.^Как определяется расчёт;Какие согласования нужны;Что происходит с объектом^Предварительная оценка без договорного основания может существенно отличаться от фактических обязательств.^Понятный порядок действий и расчёта при изменении срока сделки.
тип контейнеров^Для контейнерной платформы нужно знать типы контейнеров, массы и предполагаемые сочетания в отправке. Название «контейнерная» не описывает все допустимые схемы. Разные модификации одной семьи следует сравнивать по подтверждённой документации конкретного исполнения.^Передайте перечень контейнеров и рабочие варианты загрузки. Запросите подтверждение поддерживаемых схем, оснащения и ограничений. Отдельно учитывайте требования погрузочной стороны.^Какие типы используются;В каких сочетаниях;Что подтверждает применимость^Покупка по одному общему обозначению может не закрыть реально используемую контейнерную схему.^Перечень подтверждённых рабочих сочетаний для выбранной платформы.
крепёжные устройства|оснащение удержания^Оснащение учитывается как часть конкретной грузовой схемы, а не только как наличие на платформе. Для контейнеров и лесоматериалов требования различаются. Выбор удерживающих и крепёжных элементов связывают с грузом, исполнением вагона и подтверждённой схемой размещения.^Укажите состав оснащения и ответственность за его поставку. Технический специалист подтверждает применимость к конкретной загрузке. В документах передачи должны быть понятны комплектность и состояние переданных элементов.^Что включено в оснащение;Для какой схемы оно требуется;Кто подтверждает комплект^Цена платформы без необходимых элементов может не отражать стоимость её подготовки к намеченной перевозке.^Согласованное оснащение под подтверждённую схему груза.
опорные зоны^Для тяжёлого оборудования важно знать, где и как передаётся нагрузка от груза к транспортному решению. Общая масса не описывает её распределение. Схема должна учитывать опоры, габариты и положение центра тяжести, а её проработку выполняют технические специалисты.^Передайте чертёж оборудования с массой и подтверждёнными опорами. Укажите источник данных и возможные изменения комплектации груза. Подбор транспортера отделяют от согласования всей грузовой схемы.^Где расположены опоры;Как подтверждена нагрузка;Кто готовит схему^Совпадение общей массы с рекламным тоннажем не является достаточным основанием для перевозки.^Проверенные исходные данные об опирании и согласованная грузовая схема.
\Aисполнение оси\Z^Исполнение оси согласуют в составе требуемой колесной пары. Бытовое обозначение узла не заменяет техническую идентификацию детали и требований к её применению. Для нового элемента и сохраняемой оси нужны разные исходные подтверждения, но связь с готовой сборкой обязательна.^Попросите обозначение и документацию предлагаемого исполнения. При ремонте укажите требования принимающей площадки. Если поставщик предлагает другой вариант, его применимость согласуют отдельно.^Какова идентификация оси;С какой сборкой она согласована;Кто подтверждает применение^Неподтверждённый вариант может изменить возможности сборки и потребовать иной ремонтный маршрут.^Подтверждённое исполнение оси для согласованного узла.
совместимость буксовых узлов^Буксовое исполнение связывают с колесной парой и тележкой, в которой она применяется. Совпадение назначения детали не означает, что комплект можно автоматически установить в любую сборку. При заказе нужно сохранить точное обозначение и границы поставки.^Передайте техническое исполнение ремонтируемого узла и требования площадки. Запросите состав предлагаемого комплекта и подтверждение совместимости. Сборочные операции выделяют отдельно, если они не включены.^Каково требуемое исполнение;Какие элементы поставляются;Кто проверяет сборку^Покупка без согласования исполнения может оставить узел некомплектным или несовместимым.^Документированная буксовая комплектность для конкретной сборки.
"""

EXTRA=[]
for line in EXTRA_RULES.strip().splitlines():
    fields=line.split("^")
    assert len(fields)==6, fields
    EXTRA.append((re.compile(fields[0],re.I),*fields[1:]))

def select_rule(point):
    for fields in EXTRA:
        if fields[0].search(point): return fields
    priorities = (
        (r"проект|описание изменения|границы модернизации", "проект"),
        (r"модель|полное обозначение|полное.*модификац", "модификац"),
        (r"комплект.*документ|дефектная ведомость", "документац"),
        (r"приёмк|контроль готового|контроль результата|контроль при передаче", "испытан"),
        (r"цель контроля|организация контроля", "дефектоскоп"),
        (r"цена|затрат|стоимость альтернативной|срок действия цены|расходы", "налог"),
        (r"длительность простоя|условия оборота", "реестр партии"),
        (r"состояние имеющегося|состояние механизмов", "износ"),
        (r"ремонт сохраняемых|предстоящие работы|перечень операций", "комплект"),
        (r"порядок рассмотрения дефектов", "гаранти"),
        (r"условия поставки", "производствен"),
        (r"рабочий материал|вид удобрения|свойства материала|вид лесоматериала", "груз"),
        (r"состав предложения", "комплект"),
        (r"подготовка вагона", "передач"),
        (r"масса|объём.*загруз", "масса"),
        (r"центр.*тяжест|крепление груза", "контейнер"),
        (r"погруз|загруз|доступа в кузов", "погруз"),
        (r"выгруз|разгруз|приёмн.*оборуд", "выгруз"),
        (r"очист|чистот", "влажност"),
        (r"\bмонтаж\b", r"посадоч"),
    )
    for pattern, target in priorities:
        if re.search(pattern, point, re.I):
            return next(f for f in ENTRIES if f[0].pattern.startswith(target))
    return next(fields for fields in ENTRIES if fields[0].search(point))

def notes(point):
    return select_rule(point)[1:]

def render(a, j, point):
    i, subject, decision, points, proof, scenario = a
    why, evidence, questions, risk, done = notes(point)
    questions=questions.split(";")
    # Topic-specific object and related criterion prevent implicit universal advice.
    intro = f"Для задачи «{subject.lower()}» пункт «{point.lower()}» рассматривают применительно к выбранному объекту."
    link = f"Связанный вопрос — «{points[(j+1)%8].lower()}». Его также нужно проверить: согласование одного условия не заменяет подтверждения соседнего."
    checklist="\n".join(f"- {q}?" for q in questions)
    return f"## {j+1}. {point}\n\n{intro} {why}\n\n{evidence}\n\n{link}\n\nПеред согласованием уточните:\n\n{checklist}\n\n{risk} Ожидаемый результат: {done[0].lower()+done[1:]}\n"
